using System.IO.Compression;
using System.Text.Json;
using SharedWorldSpeedway;
namespace Robust150;
public static class Program150{
 public const string Doc="docs/experiments/robust-autonomous-racing";
 public static JsonSerializerOptions Json=>FreeLearningExperiment.Json;
 public static T Read<T>(string path){using var f=File.OpenRead(path);using Stream s=path.EndsWith(".gz",StringComparison.Ordinal)?new GZipStream(f,CompressionMode.Decompress):f;return JsonSerializer.Deserialize<T>(s,Json)!;}
 public static void Save(string name,object data){var p=Path.Combine(Doc,name);Directory.CreateDirectory(Path.GetDirectoryName(p)!);if(File.Exists(p))throw new IOException("Preserve attempt "+p);if(p.EndsWith(".gz",StringComparison.Ordinal)){using var z=new GZipStream(File.Create(p),CompressionLevel.Fastest);JsonSerializer.Serialize(z,data,Json);}else File.WriteAllText(p,JsonSerializer.Serialize(data,Json));}
 public static object SourceHashes()=>Directory.GetFiles("tools/robust-autonomous-racing","*.cs").Order().ToDictionary(p=>Path.GetFileName(p)!,p=>Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(File.ReadAllBytes(p))));
 public static void Main(string[] args){if(args.Length!=1)throw new ArgumentException("Study150 is OFF; explicit flag required.");switch(args[0]){case "--diagnosis150":Diagnosis150.Run();break;case "--detail22-150":DetailProbe150.Run();break;case "--contract-audit150":ContractAudit150.Run();break;case "--recourse-audit150":RecourseAudit150.Run();break;case "--joint-audit150":PhaseAudit150.Run(true,true);break;case "--joint-probes150":StateProbes150.Run("-joint",accepted:true,joint:true);break;case "--full-a-joint150":Experiments150.Native("robust150-joint-full-A",false,feedback:true,accepted:true,joint:true);break;case "--benchmark150":Benchmark150.Run();break;case "--accepted-audit150":PhaseAudit150.Run(true);break;case "--accepted-probes150":StateProbes150.Run("-accepted",accepted:true);break;case "--full-a-accepted150":Experiments150.Native("robust150-accepted-full-A",false,feedback:true,accepted:true);break;case "--full-b-accepted150":Experiments150.Native("robust150-accepted-full-B",true,feedback:true,accepted:true);break;case "--phase-audit150":PhaseAudit150.Run();break;case "--spatial-probes150":StateProbes150.Run("-spatial",true);break;case "--full-a-spatial150":Experiments150.Native("robust150-spatial-full-A",false,feedback:true,spatial:true);break;case "--full-b-spatial150":Experiments150.Native("robust150-spatial-full-B",true,feedback:true,spatial:true);break;case "--recover-a150":Experiments150.Native("robust150-exact-recovery-A",false,true,true,criticalPrefix:true);break;case "--recover-b150":Experiments150.Native("robust150-exact-recovery-B",true,true,true,criticalPrefix:true);break;case "--prefix-b28-150":Experiments150.Native("robust150-prefix-B-28",true,feedback:true,prefixUntil:28.4);break;case "--prefix-b45-150":Experiments150.Native("robust150-prefix-B-45",true,feedback:true,prefixUntil:45.8);break;case "--state-probes-midpoint150":StateProbes150.Run("-midpoint");break;case "--critical-midpoint150":Experiments150.Critical(true,"tube-midpoint");break;case "--state-probes150":StateProbes150.Run();break;case "--baseline-audit150":StateProbes150.BaselineAudit();break;case "--critical-tube150":Experiments150.Critical(true);break;case "--rolling-a-tube150":Experiments150.Native("robust150-tube-rolling-A",false,true,true);break;case "--full-a-tube150":Experiments150.Native("robust150-tube-full-A",false,false,true);break;case "--full-b-tube150":Experiments150.Native("robust150-tube-full-B",true,false,true);break;case "--critical150":Experiments150.Critical();break;case "--rolling-a150":Experiments150.Native("robust150-rolling-A",false,true);break;case "--full-a150":Experiments150.Native("robust150-full-A",false);break;case "--full-b150":Experiments150.Native("robust150-full-B",true);break;case "--native-diagnosis150":NativeDiagnosis150.Run();break;default:throw new ArgumentException("Unknown explicit flag.");}}
}
